def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first position where characters differ
    min_len = min(len(s_in), len(s_out))

    # Check character by character
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found first difference
            # Check if we're inserting or replacing
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            elif len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i], s_out[i:i+1], i)
            else:
                # Deletion case  
                return (s_in[i:i+1], s_out[i], i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insert at end
        return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in)-1 if s_in else 0)
    elif len(s_in) > len(s_out):
        # Delete at end
        return (s_in[len(s_out):], s_out[-1] if s_out else "", len(s_out))
    else:
        return ("", "", -1)  # No difference

